import heapq
def _b1(r):
    hasil = []
    for a, b in sorted(r):
        if a > b:
            raise ValueError
        if hasil and a <= hasil[-1][1] + 1:
            hasil[-1] = (hasil[-1][0], max(hasil[-1][1], b))
        else:
